// Resource selectors shared by the CLI commands.

import type { Resource } from "./api.ts";

// The shared client intentionally exposes only its stable Resource shape. envctl also
// needs the newer provisioner's labels to identify branch ownership.
export interface BranchResource extends Resource {
  labels?: Record<string, string>;
}

function metadataValue(r: BranchResource, key: string): string | undefined {
  return r.tags?.[key] ?? Object.entries(r.labels ?? {})
    .find(([k]) => k.toLowerCase() === key.toLowerCase())?.[1];
}

export function branchOf(r: BranchResource): string | undefined {
  return metadataValue(r, "branch");
}

export function isUntagged(r: BranchResource): boolean {
  return branchOf(r) === undefined;
}

export function byBranch(resources: BranchResource[]): Map<string, BranchResource[]> {
  const groups = new Map<string, BranchResource[]>();
  for (const r of resources) {
    const key = branchOf(r) ?? "(untagged)";
    const list = groups.get(key) ?? [];
    list.push(r);
    groups.set(key, list);
  }
  return groups;
}

// "--tag team=payments" style selectors.
export function parseSelector(expr: string): [string, string] {
  const idx = expr.indexOf("=");
  if (idx <= 0) throw new Error(`bad selector ${JSON.stringify(expr)} (expected key=value)`);
  return [expr.slice(0, idx), expr.slice(idx + 1)];
}

export function matches(r: BranchResource, selectors: [string, string][]): boolean {
  return selectors.every(([k, v]) => metadataValue(r, k) === v);
}
