test("labels identify branch ownership without changing branch value casing", () => {
  const labelled = { ...res("i-label", "instance", null, ["sub-a"]), labels: { bRaNcH: "feat-a", Team: "payments" } };
  const other = { ...res("i-other", "instance", null), labels: { Branch: "FEAT-A" } };
  const plan = buildPlan([...FIXTURE, labelled, other], "feat-a");
  assert.ok(plan.steps.some((s) => s.id === labelled.id));
  assert.ok(!plan.steps.some((s) => s.id === other.id));
  assert.deepEqual(plan.blocked, []);
  assert.ok(matches(labelled, [["team", "payments"]]));
  assert.equal(byBranch([labelled]).get("feat-a")?.length, 1);
  assert.doesNotMatch(summarize([labelled]), /untagged/);
});

