}

test("CLI preserves labels across pages for plan, list, gc and teardown", async (t) => {
  const resources = [
    resource("net", { type: "network", tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }),
    resource("boot", { stack_id: "stk-feat-a" }),
    ...Array.from({ length: 18 }, (_, i) => resource(`other-${i}`, { tags: { branch: "other" } })),
    resource("instance", { type: "instance", labels: { Branch: "feat-a" }, depends_on: ["net", "boot"] }),
    resource("dns", { type: "dns_record", labels: { bRaNcH: "feat-a" }, depends_on: ["instance"] }),
    resource("label-volume", { labels: { BRANCH: "feat-a" } }),
  ];
  const remaining = new Map(resources.map((r) => [r.id, r]));
  const deleted: string[] = [];
  let retry = true;
  let secondPages = 0;
  const server = createServer((req, res) => {
    assert.equal(req.headers.authorization, "Bearer test-token");
    res.setHeader("Content-Type", "application/json");
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      assert.equal(url.searchParams.get("limit"), "20");
      if (retry) {
        retry = false;
        res.writeHead(429, { "Retry-After": "0" });
        res.end(JSON.stringify({ error: "rate limit" }));
        return;
      }
      const cursor = url.searchParams.get("cursor");
      assert.ok(cursor === "0" || cursor === "page 2/&");
      if (cursor !== "0") secondPages++;
      const all = [...remaining.values()];
      res.end(JSON.stringify({
        resources: cursor === "0" ? all.slice(0, 20) : all.slice(20),
        next_cursor: cursor === "0" && all.length > 20 ? "page 2/&" : null,
      }));
      return;
    }
    if (req.method === "DELETE") {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      assert.ok(remaining.has(id));
      const dependents = [...remaining.values()].filter((r) => (r.depends_on as string[]).includes(id));
      if (dependents.length) {
        res.writeHead(409);
        res.end(JSON.stringify({ error: "resource has dependents", dependents: dependents.map((r) => r.id) }));
        return;
      }
      remaining.delete(id);
      deleted.push(id);
      res.end(JSON.stringify({ deleted: id }));
      return;
    }
    res.writeHead(404).end("{}");
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve())));
  const address = server.address() as { port: number };
  const run = (...args: string[]) => exec(process.execPath, ["--experimental-strip-types", "--no-warnings", cli, ...args], {
    env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" },
    timeout: 10000,
  });

  const result = await run("plan", "--branch", "feat-a", "--json");
  assert.match(result.stderr, /rate limited/);
  const plan = JSON.parse(result.stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s: { id: string }) => s.id).sort(), ["boot", "dns", "instance", "label-volume", "net"]);
  assert.match((await run("list")).stdout, /feat-a\s+4\s/);
  // The existing untagged stack resource is still reported as untagged, but labels are not.
  assert.match((await run("gc", "--untagged")).stdout, /1 untagged resources/);
  await run("teardown", "--branch", "feat-a", "--dry-run");
  assert.deepEqual(deleted, []);
  assert.match((await run("teardown", "--branch", "feat-a")).stdout, /complete \(5 resources\)/);
  assert.equal(deleted.length, 5);
  assert.equal(remaining.size, 18);
  assert.ok([...remaining.keys()].every((id) => id.startsWith("other-")));
  assert.equal(secondPages, 5);
  const empty = JSON.parse((await run("plan", "--branch", "feat-a", "--json")).stdout);
  assert.deepEqual(empty.steps, []);
});
